INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'tshwane-storm-warning-after-monday-flooding-2026-09-29',
  'Tshwane on alert for more severe storms after Monday night flooding',
  'Community', '2026-09-29', 'IOL', 'https://iol.co.za/news/weather/2026-09-29-city-of-tshwane-on-high-alert-as-severe-storms-threaten-more-flooding/',
  'The weather service has issued a Yellow Level 2 warning for severe thunderstorms over Tshwane from Tuesday afternoon until about midnight.',
  'Emergency crews in the City of Tshwane are on standby again on Tuesday after the South African Weather Service issued a Yellow Level 2 warning for severe thunderstorms. The storms are expected from the afternoon until around midnight, and the chance of rain for the region is put at 60 percent.

The warning comes after a wet Monday night, when the City''s Emergency Services Department dealt with flooded roads and homes in Mamelodi East, Meyerspark, Nellmapius, Willow Park, Wonderboom and parts of Centurion. Low-lying areas and informal settlements are considered most at risk if the heavy rain returns.

The City is asking residents to stay indoors where they can and not to drive or walk through flooded roads, bridges or swollen streams. During lightning, stay away from power lines, metal objects and fences, and do not shelter under a lone tree or other tall objects. Outdoor activities such as golf and fishing should wait until the storm has passed.',
  NULL, NULL, NULL,
  '["https://iol.co.za/news/weather/2026-09-29-city-of-tshwane-on-high-alert-as-severe-storms-threaten-more-flooding/", "https://www.joburgetc.com/news/tshwane-high-alert-severe-storms-flooding/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'waltloo-substation-explosion-power-cut-east-pretoria-2026-09-29',
  'Waltloo substation explosion cuts power to large parts of eastern Pretoria',
  'Utilities', '2026-09-29', 'City of Tshwane', 'https://www.tshwane.gov.za/?p=105383',
  'An explosion at Waltloo Substation on Tuesday morning tripped the 132 kV Njala Infeed Substation, cutting supply to many primary substations.',
  'Large parts of Tshwane lost electricity on Tuesday morning, 29 September 2026, after an explosion at Waltloo Substation. According to the City of Tshwane, the blast caused the 132 kV Njala Infeed Substation to trip, which in turn interrupted supply to a number of the primary substations that feed homes and businesses.

In alphabetical order, the affected primary substations named by the City are Heatherley, Highlands, Koedoespoort, Lynnwood, the three Mamelodi substations, Mooikloof, Pumulani, Pyramid, Scientia, Villieria, Waltloo, Wapadrand, Willows and Wingate. According to Jacaranda FM, one of the larger customers left without supply is the Council for Scientific and Industrial Research.

The City''s Emergency Services Department responded to a fire at Waltloo, and an electricity technical team has been sent to assess the damage and plan repairs. No restoration time has been given yet; the City says it will announce one, along with the exact areas affected, once the assessment is finished.

Until power returns, residents are asked to treat every part of the electricity network as live and to keep appliances unplugged, so that equipment is not damaged when supply comes back.',
  NULL, NULL, NULL,
  '["https://www.tshwane.gov.za/?p=105383", "https://www.jacarandafm.com/news/news/explosion-at-substation-disrupts-power-supply-tshwane/", "https://mybroadband.co.za/news/energy/669718-explosion-causes-widespread-power-outages-in-south-african-capital-city.html"]',
  'agent'
);
